import{_ as l,a0 as o,w as p,s as h,ao as d,I as n,x as i,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"如何 SSH 登錄到 Linux 上的特定目錄 | LCTT x X-CMD","titleTemplate":false,"description":"如何 SSH 登錄到 Linux 上的特定目錄 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何 SSH 登錄到 Linux 上的特定目錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何 SSH 登錄到 Linux 上的特定目錄 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190226 How To SSH Into A Particular Directory On Linux","title":"如何 SSH 登錄到 Linux 上的特定目錄","tag":"201903","desc":""},"relativePath":"201903/20190226 How To SSH Into A Particular Directory On Linux.md","filePath":"[post].md"}'),r={name:"201903/20190226 How To SSH Into A Particular Directory On Linux.md"};function c(g,s,k,u,b,m){const e=o("Link");return p(),h("div",null,[s[15]||(s[15]=d('<h1 id="如何-ssh-登錄到-linux-上的特定目錄" tabindex="-1">如何 SSH 登錄到 Linux 上的特定目錄 <a class="header-anchor" href="#如何-ssh-登錄到-linux-上的特定目錄" aria-label="Permalink to “如何 SSH 登錄到 Linux 上的特定目錄”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/SSH-Into-A-Particular-Directory-720x340.png" alt=""></p><p>你是否遇到過需要 SSH 登錄到遠程服務器並立即 <code>cd</code> 到一個目錄來繼續交互式作業？你找對地方了！這個簡短的教程描述瞭如何直接 SSH 登錄到遠程 Linux 系統的特定目錄。而且不僅是 SSH 登錄到特定目錄，你還可以在連接到 SSH 服務器後立即運行任何命令。這些沒有你想的那麼難。請繼續閲讀。</p><h3 id="ssh-登錄到遠程系統的特定目錄" tabindex="-1">SSH 登錄到遠程系統的特定目錄 <a class="header-anchor" href="#ssh-登錄到遠程系統的特定目錄" aria-label="Permalink to “SSH 登錄到遠程系統的特定目錄”">​</a></h3><p>在我知道這個方法之前，我通常首先使用以下命令 SSH 登錄到遠程系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh user@remote-system</span></span></code></pre></div><p>然後如下 <code>cd</code> 進入某個目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd &lt;some-directory&gt;</span></span></code></pre></div><p>然而，你不需要使用兩個單獨的命令。你可以用一條命令組合並簡化這個任務。</p><p>看看下面的例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 &#39;cd /home/sk/ostechnix ; bash&#39;</span></span></code></pre></div><p>上面的命令將通過 SSH 連接到遠程系統 （192.168.225.22） 並立即進入名為 <code>/home/sk/ostechnix/</code> 的目錄，並停留在提示符中。</p><p>這裏，<code>-t</code> 標誌用於強制分配偽終端，這是一個必要的交互式 shell。</p><p>以下是上面命令的輸出：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/ssh-1.gif" alt=""></p><p>你也可以使用此命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 &#39;cd /home/sk/ostechnix ; exec bash&#39;</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 &#39;cd /home/sk/ostechnix &amp;&amp; exec bash -l&#39;</span></span></code></pre></div><p>這裏，<code>-l</code> 標誌將 bash 設置為登錄 shell。</p><p>在上面的例子中，我在最後一個參數中使用了 <code>bash</code>。它是我的遠程系統中的默認 shell。如果你不知道遠程系統上的 shell 類型，請使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 &#39;cd /home/sk/ostechnix &amp;&amp; exec $SHELL&#39;</span></span></code></pre></div><p>就像我已經説過的，它不僅僅是連接到遠程系統後 <code>cd</code> 進入目錄。你也可以使用此技巧運行其他命令。例如，以下命令將進入 <code>/home/sk/ostechnix/</code>，然後執行命令 <code>uname -a</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 &#39;cd /home/sk/ostechnix &amp;&amp; uname -a &amp;&amp; exec $SHELL&#39;</span></span></code></pre></div><p>或者，你可以在遠程系統上的 <code>.bash_profile</code> 文件中添加你想在 SSH 登錄後執行的命令。</p><p>編輯 <code>.bash_profile</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nano ~/.bash_profile</span></span></code></pre></div><p>每個命令一行。在我的例子中，我添加了下面這行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /home/sk/ostechnix &gt;&amp; /dev/null</span></span></code></pre></div><p>保存並關閉文件。最後，運行以下命令更新修改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bash_profile</span></span></code></pre></div><p>請注意，你應該在遠程系統的 <code>.bash_profile</code> 或 <code>.bashrc</code> 文件中添加此行，而不是在本地系統中。從現在開始，無論何時登錄（無論是通過 SSH 還是直接登錄），<code>cd</code> 命令都將執行，你將自動進入 <code>/home/sk/ostechnix/</code> 目錄。</p><p>就是這些了。希望這篇文章有用。還有更多好東西。敬請關注！</p><p>乾杯!</p><hr>',35)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),t(e,{href:"https://www.ostechnix.com/how-to-ssh-into-a-particular-directory-on-linux/"},{default:a(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-ssh-into-a-particular-directory-on-linux/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=i("作者：",-1)),t(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:a(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const y=l(r,[["render",c]]);export{S as __pageData,y as default};
